const MAIN_KEY="al_siddique_paper_store";
function norm(value){return String(value||"").trim().toLowerCase().replace(/[^a-z0-9_-]+/g,"-").replace(/^-+|-+$/g,"");}
function getScope(user){const tenant=norm(user.tenant_id||user.tenantId);if(tenant)return "tenant-"+tenant;const school=norm(user.school_id||user.schoolId);if(school)return "school-"+school;const code=norm(user.school_code||user.schoolCode);if(code)return "code-"+code;const email=norm(user.email);return email?"user-"+email:"public";}
let tries=0;
function attempt(){
 if(++tries>60)return;
 try {
  const rawUser=localStorage.getItem("al_siddique_user")||sessionStorage.getItem("al_siddique_user");
  if(!rawUser){setTimeout(attempt,1200);return;}
  const user=JSON.parse(rawUser);
  const school=String(user.school_id||user.schoolId||user.tenant_id||user.tenantId||"");
  const role=String(user.role||"").toLowerCase().trim();
  if(school!=="1"||!["admin","principal","super_admin"].includes(role))return;
  const scope=getScope(user);const key=scope==="public"?MAIN_KEY:MAIN_KEY+"__"+scope;
  const fromSession=sessionStorage.getItem(key);const source=fromSession!==null?"session":"local";
  const storage=source==="session"?sessionStorage:localStorage;
  const raw=fromSession!==null?fromSession:localStorage.getItem(key);
  if(!raw){setTimeout(attempt,900);return;}
  const store=JSON.parse(raw);if(!store||!Array.isArray(store.savedPapers))return;
  const arr=store.savedPapers;
  if(arr.some(p=>p&&((p.id===targetPaper.id)||(p.name===targetPaper.name&&String(p.config?.totalMarks)==="25"))))return;
  const priorIds=arr.map(p=>String(p?.id??""));
  const revised={...store,savedPapers:[targetPaper,...arr]};
  storage.setItem(key,JSON.stringify(revised));
  const verify=JSON.parse(storage.getItem(key));
  if(verify.savedPapers.length!==priorIds.length+1||!priorIds.every((id,i)=>String(verify.savedPapers[i+1]?.id??"")===id))throw Error("saved papers preservation readback failed");
  console.info("ASSPS Class Four Measurement imported into native Saved Papers",targetPaper.id,verify.savedPapers.length);
  window.dispatchEvent(new Event("al_siddique_paper_store_updated"));
  if(location.pathname.includes("/paper-generator"))setTimeout(()=>location.reload(),180);
 } catch(e) {console.warn("ASSPS assessment import not committed: "+e.message);}
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",attempt,{once:true});else attempt();
